for(const i of buziosGuidePages[ROOT+'mes-a-mes/'].sections.flatMap(s=>s.items)){if(i.title.ES==='Quiero playa tranquila'&&!i.photo)i.photo='Ferradura';if(i.title.ES==='Quiero fiesta y agenda'&&!i.photo)i.photo='Orla Bardot';if(i.title.ES==='Quiero mejores precios'&&!i.photo)i.photo='Geribá';}

