const bzEcPhotos={solo:[{src:"https://mediumturquoise-stinkbug-270478.hostingersite.com/FOTOS/HOME/BUZIOS/GUIA%20BUZIOS/VIAJANDO%20SOLA/1122e2c0350059b4af30dbb27835fc8b.jpg",name:"Viajar sola y disfrutar los paisajes costeros",width:1200,height:800},{src:"https://mediumturquoise-stinkbug-270478.hostingersite.com/FOTOS/HOME/BUZIOS/GUIA%20BUZIOS/VIAJANDO%20SOLA/669f3f69ad6e72f6c57f806d10c9393a.jpg",name:"Paseos junto al mar durante un viaje independiente",width:1200,height:800},{src:"https://mediumturquoise-stinkbug-270478.hostingersite.com/FOTOS/HOME/BUZIOS/GUIA%20BUZIOS/VIAJANDO%20SOLA/c82eade186edfbdb48d78228a8a925f5.jpg",name:"Momentos de calma junto al mar",width:1200,height:800}],months:[{src:"https://mediumturquoise-stinkbug-270478.hostingersite.com/FOTOS/HOME/BUZIOS/GUIA%20BUZIOS/MES%20A%20MES/BUZIOS%20MES%20A%20MES%202.jpg",name:"Verano y playas de Búzios",width:1200,height:800},{src:"https://mediumturquoise-stinkbug-270478.hostingersite.com/FOTOS/HOME/BUZIOS/GUIA%20BUZIOS/MES%20A%20MES/BUZIOS%20MES%20A%20MES.jpg",name:"Ambiente de Carnaval en Búzios",width:1200,height:800},{src:"https://mediumturquoise-stinkbug-270478.hostingersite.com/FOTOS/HOME/BUZIOS/GUIA%20BUZIOS/MES%20A%20MES/BUZIOS%20MES%20A%20MES%203.jpg",name:"Búzios iluminado por la noche",width:1200,height:800},{src:"https://mediumturquoise-stinkbug-270478.hostingersite.com/FOTOS/HOME/BUZIOS/GUIA%20BUZIOS/MES%20A%20MES/B%C3%BAzios-fica-entre-as-cidades-mais-procuradas-como-destino-para-o-Carnaval-2020.jpg",name:"Imagen de archivo de Carnaval en Búzios",width:1200,height:800}],access:[{src:"https://mediumturquoise-stinkbug-270478.hostingersite.com/FOTOS/HOME/BUZIOS/GUIA%20BUZIOS/ACCESIBILIDAD/ACCESIBILIDAD%20PLAYA%20AZEDA%202.jpg",name:"Trabajos de mejora del acceso a Praia da Azeda",width:1200,height:800},{src:"https://mediumturquoise-stinkbug-270478.hostingersite.com/FOTOS/HOME/BUZIOS/GUIA%20BUZIOS/ACCESIBILIDAD/ACCESIBILIDAD%20PLAYA%20AZEDA.jpg",name:"Baño de mar asistido en Praia da Azeda",width:1200,height:800},{src:"https://mediumturquoise-stinkbug-270478.hostingersite.com/FOTOS/HOME/BUZIOS/GUIA%20BUZIOS/ACCESIBILIDAD/PROYECTO%20MAR%20PARA%20TODOS.jpg",name:"Participantes del proyecto Mar para Todos",width:1200,height:800},{src:"https://mediumturquoise-stinkbug-270478.hostingersite.com/FOTOS/HOME/BUZIOS/GUIA%20BUZIOS/ACCESIBILIDAD/SILLA%20PCD%20PLAYA.jpg",name:"Silla anfibia utilizada para facilitar el acceso al agua",width:1200,height:800}]};
const bzEcGuide=(slug)=>buziosGuidePages[ROOT+slug+'/'];
const bzEcCard=(es,pt,en,esCopy,ptCopy,enCopy,photo)=>item(T(es,pt,en),T(esCopy,ptCopy,enCopy),'',photo);
const bzEcSection=(es,pt,en,esIntro,ptIntro,enIntro,arr)=>section(T(es,pt,en),T(esIntro,ptIntro,enIntro),A(...arr),'');
{
 const p=bzEcGuide('viajar-solo');
 p.sections.splice(1,0,bzEcSection('Búzios a tu ritmo: libertad con un buen plan','Búzios no seu ritmo: liberdade com planejamento','Búzios at your pace: freedom with a plan',
 'Viajar sin compañía no significa pasar el viaje aislado. Puedes decidir cuándo bajar a la playa, caminar por el centro o quedarte mirando el mar sin negociar horarios. Mi consejo es sencillo: organiza el regreso antes de improvisar el día.','Viajar sem companhia não significa ficar isolado. Aproveite para escolher seu ritmo, caminhar pelo centro e descobrir paisagens com tranquilidade. Minha dica: planeje a volta antes de improvisar o dia.','Travelling alone does not mean spending the trip isolated. Set your own pace for the beach, waterfront walks and quiet moments. My tip: plan your return before improvising your day.',[
 bzEcCard('01 · Tu primera caminata por Búzios','01 · Sua primeira caminhada por Búzios','01 · Your first walk in Búzios',
 'Empieza por la zona de Rua das Pedras y Orla Bardot cuando haya movimiento. Es un buen recorrido para orientarte, localizar lugares donde comer y reconocer los puntos de regreso. Haz una pausa para disfrutar del paisaje: no hace falta contratar una excursión para comenzar a sentir Búzios. Comprueba el estado de las veredas y evita bajar a rocas mojadas solo para conseguir una fotografía.','Comece pela Rua das Pedras e pela Orla Bardot em horários movimentados. Reconheça referências, locais para comer e pontos de retorno. Desfrute da paisagem, mas não se arrisque nas pedras molhadas por uma foto.','Start around Rua das Pedras and Orla Bardot while the area is active. Find your bearings, food stops and the route back. Enjoy the views, but do not climb wet rocks just for a photo.',bzEcPhotos.solo[0]),
 bzEcCard('02 · Conversar, conocer gente o disfrutar del silencio','02 · Conhecer pessoas ou aproveitar o silêncio','02 · Meet people or enjoy the quiet',
 'Un café, una clase o una actividad grupal confirmada pueden abrir conversaciones de forma natural. También está perfecto ir a cenar solo o leer junto al mar. No aceptes encuentros en lugares aislados ni entregues datos de tu alojamiento a desconocidos; elegir tus límites forma parte del placer de viajar por tu cuenta.','Um café ou uma atividade coletiva confirmada pode facilitar conversas. Também é ótimo jantar sozinho ou ler à beira-mar. Evite encontros em áreas isoladas e proteja as informações da hospedagem.','A café or a verified group activity can make meeting people easier. Dining alone or reading by the water is equally enjoyable. Avoid isolated meeting points and protect your accommodation details.',bzEcPhotos.solo[1]),
 bzEcCard('03 · Playas y paisajes sin correr','03 · Praias e paisagens sem pressa','03 · Beaches and views without rushing',
 'Escoge una playa por sus condiciones reales del día, no solo por una fotografía: viento, oleaje, acceso y servicios cambian la experiencia. Lleva agua, protección solar y una forma segura de guardar lo indispensable. Si visitas miradores o costones, prioriza recorridos concurridos y autorizados; no improvises senderos aislados ni nades sin compañía en zonas sin vigilancia.','Escolha a praia pelas condições do dia: vento, ondas, acesso e serviços. Leve água e proteção solar. Em mirantes e costões, prefira caminhos autorizados e movimentados; não improvise trilhas isoladas.','Choose beaches for actual daily conditions: wind, waves, access and facilities. Carry water and sun protection. Use established routes at viewpoints and rocky shores, and avoid isolated trails.',bzEcPhotos.solo[2])
 ]));
 p.notice=T('Dato de Ernestinho: viajar solo es disfrutar tu libertad con tranquilidad. Guarda el nombre y dirección de tu hospedaje, confirma el transporte nocturno y comparte tu plan con alguien de confianza.','Dica do Ernestinho: aproveite a liberdade com tranquilidade. Salve o endereço da hospedagem, confira o transporte à noite e compartilhe o plano com alguém de confiança.','Ernestinho’s tip: enjoy the freedom with peace of mind. Save your accommodation address, check night transport and share your plan with someone you trust.');
}
{
 const p=bzEcGuide('mes-a-mes');
 p.sections.splice(1,0,bzEcSection('Las estaciones también cuentan historias','As estações também contam histórias','Every season tells a different story',
 'No se trata de escoger un mes ganador: enero y febrero tienen energía veraniega; entre otoño e invierno puedes encontrar otros ritmos; y la primavera anuncia nuevas posibilidades de paseos. Aquí tienes cuatro imágenes para comparar ambientes, sin confundir fotografías de archivo con la agenda actual.','Não existe um único mês vencedor: verão, outono, inverno e primavera oferecem ritmos diferentes. As imagens mostram ambientes e não garantem a programação atual.','There is no single best month: summer, autumn, winter and spring each have a different rhythm. The photos capture atmosphere rather than promising current events.',[
 bzEcCard('01 · Verano: energía y demanda','01 · Verão: energia e movimento','01 · Summer: energy and crowds','En enero y febrero aumenta el movimiento por vacaciones, especialmente en fines de semana y feriados. Reserva alojamiento y traslados con anticipación; busca playas acordes con el viento y deja alternativas por si aparecen chaparrones de verano.','Em janeiro e fevereiro as férias aumentam o movimento. Reserve hospedagem e transporte, confira vento e mar e tenha planos alternativos para pancadas de chuva.','January and February can be busy with school holidays. Book accommodation and transport early, check wind and sea conditions and leave room for summer rain.',bzEcPhotos.months[0]),
 bzEcCard('02 · Carnaval: ambiente, no calendario duplicado','02 · Carnaval: clima de festa, sem duplicar a agenda','02 · Carnival atmosphere, not a duplicated calendar','El Carnaval cambia de fechas cada año y puede concentrar visitantes. Esta imagen ayuda a entender el ambiente, pero la programación, los horarios y los blocos vigentes deben consultarse en el botón Eventos de Búzios.','O Carnaval muda de data a cada ano. Consulte blocos, horários e a programação vigente exclusivamente na seção Eventos de Búzios.','Carnival dates change every year. Check current street parties and schedules in the dedicated Búzios Events section.',bzEcPhotos.months[1]),
 bzEcCard('03 · Búzios después del atardecer','03 · Búzios depois do pôr do sol','03 · Búzios after sunset','Una noche en Rua das Pedras o junto a la Orla Bardot puede formar parte del viaje en cualquier estación. En los meses más frescos, lleva una capa liviana y verifica cómo regresar, especialmente si te hospedas lejos del centro.','A Rua das Pedras e a Orla Bardot também são convites para passeios noturnos. Em noites mais frescas, leve uma camada extra e planeje a volta.','Rua das Pedras and Orla Bardot offer evening walks across seasons. Bring a light extra layer on cooler nights and plan your return.',bzEcPhotos.months[2]),
 bzEcCard('04 · Feriados y fotografías de archivo','04 · Feriados e imagens de arquivo','04 · Holidays and archive photographs','Una imagen concurrida transmite bien por qué conviene reservar en Carnaval. Esta fotografía es de archivo, asociada a 2020: no representa necesariamente la programación ni la ocupación de este año. Para fechas concretas consulta Eventos y el calendario oficial.','Esta fotografia de arquivo está associada ao Carnaval de 2020. Não representa necessariamente os eventos nem o movimento atual: confira a seção Eventos e a agenda oficial.','This archive image is associated with Carnival 2020. It does not represent this year’s schedule or crowd levels. Check Events and the official calendar.',bzEcPhotos.months[3])
 ]));
}
{
 const p=bzEcGuide('accesibilidad');
 p.sections.splice(1,0,bzEcSection('Praia da Azeda y el derecho a disfrutar del mar','Praia da Azeda e o direito de aproveitar o mar','Praia da Azeda and access to the sea',
 'Búzios tiene experiencias de inclusión que vale la pena conocer, pero ninguna fotografía garantiza accesibilidad autónoma todos los días. Hay que comprobar toda la cadena: llegada, pendiente, rampa, arena, silla anfibia, personal de apoyo y regreso.','Búzios possui iniciativas de inclusão, mas nenhuma fotografia garante acesso autônomo todos os dias. Confira chegada, rampa, areia, cadeira anfíbia, apoio e retorno.','Búzios has inclusive initiatives, but a photograph does not guarantee independent access every day. Check the approach, ramp, sand, amphibious chair, staff and return journey.',[
 bzEcCard('01 · Praia da Azeda: una rampa no es toda la ruta','01 · Praia da Azeda: a rampa não é o trajeto inteiro','01 · Praia da Azeda: a ramp is not the entire route','En mayo de 2025 se informó sobre una rampa que facilitaba el acceso a la franja de arena de Praia da Azeda. Es una mejora importante, pero antes de viajar hay que confirmar su estado actual, los desniveles desde el punto de llegada, el tramo sobre arena y la disponibilidad de asistencia. No recomendamos tratar la playa como completamente accesible sin comprobar esas condiciones.','Em maio de 2025 foi noticiada uma rampa que facilitava a chegada à areia da Praia da Azeda. Antes da visita, confirme seu estado, as inclinações, a areia e o apoio disponível. Isso não significa acessibilidade integral e autônoma garantida.','A ramp helping visitors reach Praia da Azeda was reported in May 2025. Before travelling, confirm its current condition, gradients, sandy sections and available assistance. This does not guarantee full independent access.',bzEcPhotos.access[0]),
 bzEcCard('02 · Baño de mar con ayuda profesional','02 · Banho de mar com apoio profissional','02 · Assisted sea bathing','El baño asistido requiere evaluar mareas, oleaje, condiciones del acceso, equipamiento y disponibilidad de personal capacitado. La participación en una edición del programa no significa que haya sillas o salvavidas especializados todos los días. Pide confirmación para tu fecha específica.','O banho assistido depende de maré, ondas, equipamento e equipe capacitada. A participação em uma edição não garante cadeiras ou apoio especializado diariamente. Confirme a data.','Assisted bathing depends on tides, surf, equipment and trained staff. A previous event does not guarantee daily availability. Confirm your exact date.',bzEcPhotos.access[1]),
 bzEcCard('03 · Mar para Todos: el proyecto municipal','03 · Mar para Todos: o projeto municipal','03 · Mar para Todos: the municipal initiative','Mar para Todos es una iniciativa de la Prefeitura de Armação dos Búzios, mediante la Secretaría de la Persona con Discapacidad. Se documentaron actividades en Praia da Azeda en mayo y agosto de 2025, con sillas anfibias y acompañamiento. Un informe de agosto de 2025 mencionó también Praia do Forno y el canto izquierdo de Geribá, y la posibilidad de solicitar participación con antelación. Contacto publicado entonces: (22) 2350-6066; verifica que siga vigente y confirma fecha, playa y requisitos.','Mar para Todos é uma iniciativa da Prefeitura de Armação dos Búzios por meio da Secretaria da Pessoa com Deficiência. Houve ações documentadas na Azeda em maio e agosto de 2025 com cadeiras anfíbias e equipe de apoio. Uma notícia de agosto citou também Forno e o canto esquerdo de Geribá. Contato divulgado à época: (22) 2350-6066. Confirme telefone, data, praia e requisitos.','Mar para Todos is run by the Búzios municipality through its disability affairs department. Activities with amphibious chairs and trained support were reported at Azeda in May and August 2025. An August report also mentioned Forno and the left side of Geribá. The phone published then was +55 22 2350-6066; verify current contact details, dates and eligibility.',bzEcPhotos.access[2]),
 bzEcCard('04 · Qué es una silla anfibia','04 · O que é uma cadeira anfíbia','04 · What is an amphibious chair?','Una silla anfibia está diseñada para facilitar el desplazamiento sobre arena y la entrada asistida en el agua. No debe confundirse con una silla de ruedas convencional ni asumirse que funciona sin personal de apoyo. Pregunta cómo se realiza la transferencia, si hay un protocolo de seguridad, y si el equipamiento se adapta a tus necesidades.','Uma cadeira anfíbia facilita o deslocamento na areia e a entrada assistida na água. Ela não substitui uma cadeira convencional nem dispensa apoio. Pergunte sobre transferência, segurança e adaptação às necessidades individuais.','An amphibious chair can help with movement over sand and assisted water entry. It is not an ordinary wheelchair and should not be assumed to work without support. Ask about transfers, safety procedures and suitability.',bzEcPhotos.access[3])
 ]));
 p.notice=T('Dato de Ernestinho: Mar para Todos (Búzios) no es el mismo proyecto que Praia Para Todos del Instituto Novo Ser. Confirma con la Secretaría municipal el funcionamiento actual antes de organizar tu visita a Praia da Azeda.','Dica do Ernestinho: Mar para Todos (Búzios) não é o mesmo projeto que Praia Para Todos, do Instituto Novo Ser. Confirme com a Secretaria municipal o funcionamento atual antes de visitar a Azeda.','Ernestinho’s tip: Búzios’ Mar para Todos is different from the Instituto Novo Ser’s Praia Para Todos. Confirm current municipal arrangements before planning an Azeda visit.');
}
